SELECT  FROM 
WHERE rx.status='ISSUED' AND p.owner_user_id=#{userId}
ORDER BY rx.issued_at DESC,rx.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM med_prescription rx JOIN med_encounter e ON e.id=rx.encounter_id
JOIN med_appointment a ON a.id=e.appointment_id JOIN med_patient p ON p.id=a.patient_id
WHERE rx.status='ISSUED' AND p.owner_user_id=#{userId}
